"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[813],{6813:(e,a,t)=>{t.d(a,{$g:()=>h,If:()=>u,Il:()=>l,XV:()=>c,ZE:()=>r,_7:()=>o,_e:()=>d,eh:()=>s,he:()=>g,oW:()=>m,vE:()=>n,wk:()=>i});let i={name:"Samriddhi Bhog",tagline:"From Grain to Goodness.",company:"Shree Hanuman Atta Mills Pvt Ltd",address:"T.N. Mukherjee Road, Kusagachi, Raghunathpur, Bonderbill, Dankuni, Hooghly, West Bengal 712247",phone:"033-2659 6736",phoneHref:"tel:+913326596736",phoneIntl:"+91-33-2659-6736",whatsapp:"918100768309",email:"info@samriddhibhog.com",fssai:"12819007000215",since:"1950",amazon:"https://amzn.in/d/07KuVYZw",facebook:"https://www.facebook.com/samriddhibhogindia",social:[{platform:"instagram",id:"Dd6Zai8j1_l"},{platform:"facebook",type:"video",url:"https://www.facebook.com/reel/1105491595568333/"},{platform:"instagram",id:"Dd6ZW6LSTJN"},{platform:"facebook",type:"video",url:"https://www.facebook.com/reel/1738649707432413/"},{platform:"instagram",id:"Dd6ZW5pvnI0"},{platform:"facebook",type:"post",url:"https://www.facebook.com/samriddhibhogindia/posts/pfbid0oHghoN6BxstDeiZcZ189ySnhdkNieHSBBJxLGcwerwwWUR7HLLDTuq5kY975aWFml"},{platform:"instagram",id:"Dd6ZW6lvNQt"},{platform:"facebook",type:"video",url:"https://www.facebook.com/reel/1077476308545146/"},{platform:"instagram",id:"Dd1Q_wiDFPP"},{platform:"instagram",id:"DdwDxdpRnXs"},{platform:"instagram",id:"DdoWbDTv0o-"},{platform:"instagram",id:"DdoWYO4vvgZ"},{platform:"instagram",id:"DdoWWHnPxL7"}],slogan:"Har Niwale Mein Samriddhi!",mapEmbed:"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d1843.5!2d88.3110216!3d22.675661!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x39f8833bc6ea4201%3A0xd48b89cbd755fe17!2sShree%20Hanuman%20Atta%20Mills%20Pvt%20Ltd.!5e0!3m2!1sen!2sin!4v1717100000000!5m2!1sen!2sin",mapLink:"https://www.google.com/maps/search/?api=1&query=Shree+Hanuman+Atta+Mills+Pvt+Ltd+Dankuni",instagram:{handle:"samriddhibhog"},location:"West Bengal, India"},o={title:"A Legacy Ground with Care Since 1950",intro:"In 1950, Shri Hanuman Prasad Agarwala began a humble Modi Khana shop with a small traditional chakki — where families came not just to buy atta, but for the trust of freshly ground wheat.",body:["Every day, carefully selected wheat was ground in small quantities, carrying forward a simple belief: “Good atta is not manufactured, it is made with care.” As generations changed, the promise remained the same.","Taking forward his father’s values, his son transformed this traditional chakki into a modern flour mill — combining age-old chakki wisdom with advanced technology. Today, Samriddhi Bhog products are manufactured at Shree Hanuman Atta Mills Pvt. Ltd., where grains and pulses go through a complete process of:"],process:["Careful Wheat Selection","Advanced Cleaning & Sorting","Stone Chakki Processing","Lab Testing & Automated Packing, ensuring consistent quality"],closing:"With stone chakkis, a production capability of 100 MT/day, and modern quality systems — every pack carries the same purity that started in a small Modi Khana more than six decades ago.",tagline:"From one Modi Khana shop in 1950… to a 100 MT/day production capacity.",summary:"Samriddhi Bhog combines the age-old goodness of stone chakki grinding with advanced cleaning, controlled processing, and hygienic automated packing — bringing wholesome flour to every household.",timeline:[{y:"1950",k:"Modi Khana",d:"Traditional chakki"},{y:"",k:"Generations of experience",d:""},{y:"2003",k:"Modern flour mill",d:"Shree Hanuman Atta Mills"},{y:"Today",k:"100 MT/day",d:"Quality testing \xb7 Automated packing"},{y:"",k:"Samriddhi Bhog",d:""}],stats:[{value:"1950",label:"Year founded"},{value:"20+",label:"Years of milling"},{value:"100 MT",label:"Milled every day"},{value:"10,000+",label:"Happy families"}]},n=[{k:"Mill Hygiene First",lede:"Every grain undergoes a rigorous, automated cleaning process.",d:"Because consistent quality starts with the grain.",img:"/img/trust-hygiene.webp",alt:"A Samriddhi Bhog team member in gloves, mask and hairnet checking wheat from a sack",pos:"50% 30%"},{k:"Zero Adulteration",lede:"Nothing added. Nothing compromised.",d:"No maida blending, no whiteners, no chemicals. Every batch is lab-tested to ensure purity and consistency.",img:"/img/trust-lab.webp",alt:"A lab technician holding up a test tube during a purity test",pos:"45% 45%"},{k:"Advanced Milling Standards",lede:"Precision milling, built around quality.",d:"Our automated processes are designed to maintain cleanliness, consistency, and quality at every stage of milling.",img:"/img/trust-milling.webp",alt:"The Samriddhi Bhog mill floor with its row of stone chakkis",pos:"55% 55%"},{k:"No Preservatives",lede:"Nothing artificial. Nothing unnecessary.",d:"We make our flour without preservatives, keeping the product as close to its natural state as possible.",img:"/img/trust-natural.webp",alt:"Ripe wheat ears in a golden field at sunset",pos:"50% 45%"},{k:"Consistent Quality",lede:"The same taste. The same texture. Every time.",d:"Consistent milling means your recipes perform the way you expect — order after order, batch after batch.",img:"/img/trust-quality.webp",alt:"A lab technician in gloves placing a flour sample on a moisture analyser",pos:"40% 50%"},{k:"10,000+ Happy Families",lede:"Trusted by 10,000+ families and businesses.",d:"From kirana stores and restaurants to sweet shops and caterers, customers across the region rely on us every day.",img:"/img/family-kitchen.webp",alt:"A woman making rotis in a sunlit home kitchen, with dhokla and besan on the table",pos:"50% 38%",note:"Creative visualisation"}],s=[{k:"Premium Grain Selection",d:"Only the finest grain varieties, sourced directly from trusted farmers."},{k:"Cleaning & Sorting",d:"Grain is thoroughly cleaned, de-stoned, and sorted before milling."},{k:"Washing",d:"Every grain is washed thoroughly to remove impurities and retain natural ingredients."},{k:"Chakki Milling",d:"Ground slow and cool on traditional chakki — to retain natural ingredients."},{k:"Quality Testing",d:"Passes through multiple lab tests for quality and purity checks."},{k:"Hygienic Packaging",d:"Sealed fresh in food-grade packaging, ensuring purity from mill to your kitchen."}],r=[{id:"atta",index:"01",name:"Atta",packName:"Chakki Atta",subtitle:"Wheat Flour",ingredients:"Whole wheat",kind:"Whole wheat flour",size:"5 kg",sizes:["1 kg","5 kg"],price:null,pack:"/img/pack-atta.webp",packSm:"/img/pack-atta-sm.webp",scene:"/img/roti.webp",sceneAlt:"A stack of soft rotis on a wooden plate",line:"The everyday dough.",description:"Our flagship product. Zero blending, zero chemicals. The roti that brings families back to the table.",uses:["Rotis & phulkas","Parathas","Puris"],packClaims:["Chakki Ground","No Maida","No Added Preservatives","Rich in Dietary Fibre"],tone:{bg:"#F3EBDD",ink:"#4A1F1C",accent:"#7A2622"}},{id:"besan",index:"02",name:"Besan",packName:"Chana Besan",subtitle:"Gram Flour",ingredients:"Bengal gram (chana)",kind:"Gram flour",size:"500 g",sizes:["500 g"],price:null,pack:"/img/pack-besan.webp",packSm:"/img/pack-besan-sm.webp",scene:"/img/besan-chilla.webp",sceneAlt:"Golden besan chillas with green chutney",line:"Golden by nature.",description:"Finely ground chana dal. Rich aroma, no blending. The right besan for chilla, kadhi, and ladoo.",uses:["Chilla","Pakora batter","Kadhi & ladoo"],packClaims:["Chakki Ground","No Added Preservatives","Rich in Protein","Rich in Dietary Fibre"],tone:{bg:"#F5EAD0",ink:"#4D3208",accent:"#C0870B"}},{id:"dalia",index:"03",name:"Dalia",packName:"Wheat Dalia",subtitle:"Broken Wheat",ingredients:"Whole wheat",kind:"Broken wheat",size:"500 g",sizes:["500 g"],price:null,pack:"/img/pack-dalia.webp",packSm:"/img/pack-dalia-sm.webp",scene:"/img/dalia-bowl.webp",sceneAlt:"A pan of savoury vegetable dalia with lemon",line:"Breakfast, broken right.",description:"Coarsely cracked whole wheat. High-fibre, clean, nutty taste. Porridge, khichdi, and morning meals.",uses:["Porridge","Vegetable upma","Khichdi-style bowls"],packClaims:["Chakki Ground","No Added Preservatives","Rich in Dietary Fibre"],tone:{bg:"#F2E7D5",ink:"#4E2C12",accent:"#A6621F"}},{id:"sattu",index:"04",name:"Sattu",packName:"Chana Sattu",subtitle:"Roasted Gram Flour",ingredients:"Roasted chana",kind:"Roasted gram flour",size:"500 g",sizes:["500 g"],price:null,pack:"/img/pack-sattu.webp",packSm:"/img/pack-sattu-sm.webp",scene:"/img/sattu-drink.webp",sceneAlt:"A glass of sattu drink with roasted chana and lemon",line:"Roasted, then ground.",description:"Slow-roasted, coarsely ground. Traditional power food — protein-rich and deeply nourishing.",uses:["Sattu drinks","Litti filling","Savoury stuffings"],packClaims:["Chakki Ground","No Added Preservatives","Rich in Protein"],tone:{bg:"#F4E6D6",ink:"#5A2A12",accent:"#B8531F"}}],l=e=>r.find(a=>a.id===e),d=[{slug:"soft-roti",title:"Soft Roti",product:"atta",image:"/img/roti-kitchen.webp",alt:"Freshly puffed rotis stacked beside the stove",intro:"A simple whole wheat dough, rested and cooked on a hot tawa.",prep:"35 min",cook:"20 min",serves:"4",ingredients:["2 cups (260 g) Samriddhi Bhog Atta","3/4 cup (180 ml) water, added gradually","1/4 tsp salt (optional)","1 tsp neutral oil or ghee (optional)","Extra atta for dusting"],method:["Combine the atta and salt in a wide bowl. Make a well in the centre.","Add the water a little at a time, mixing with your fingers until the flour comes together.","Knead for 8 to 10 minutes until smooth and soft but not sticky. Knead in the oil or ghee, if using.","Cover and rest the dough at room temperature for 20 minutes.","Heat a tawa over medium-high heat. Divide the dough into 8 balls.","Dust one ball lightly and roll it into a thin, even round about 15 cm across.","Cook on the tawa for 20–30 seconds until small bubbles appear, then turn. Cook the second side for about 30 seconds.","Turn once more and press the edges gently with a clean cloth until the roti puffs and has browned spots."],notes:["Atta absorbs water differently across batches and weather, so add it gradually.","Keep the dough and finished rotis covered to stop them drying out."]},{slug:"sattu-sharbat",title:"Sattu Sharbat",product:"sattu",image:"/img/sattu-drink.webp",alt:"A chilled glass of savoury sattu sharbat",intro:"Roasted chana flour whisked with chilled water, lemon and roasted cumin.",prep:"10 min",cook:"0 min",serves:"2",ingredients:["4 tbsp (40 g) Samriddhi Bhog Sattu","2 cups (500 ml) chilled water","2 tbsp lemon juice","1/2 tsp roasted cumin powder","1/4 tsp black salt","Salt to taste","1 tbsp chopped coriander","1 small green chilli, finely chopped (optional)"],method:["Whisk the sattu with about 1/2 cup of the water into a smooth, lump-free paste.","Pour in the remaining water while whisking. Add lemon juice, cumin, black salt and salt.","Stir in the coriander and chilli, taste, and adjust lemon or salt.","Stir once more, divide between two glasses and serve immediately."],notes:["Making a paste first prevents dry pockets of sattu.","Sattu settles naturally — stir again if the drink stands."]},{slug:"vegetable-dalia",title:"Vegetable Dalia",product:"dalia",image:"/img/dalia-bowl.webp",alt:"Savoury vegetable dalia in a black pan",intro:"Broken wheat cooked with vegetables and gentle spices in one pan.",prep:"15 min",cook:"40 min",serves:"4",ingredients:["1 cup (180 g) Samriddhi Bhog Dalia","1 tbsp neutral oil","1 tsp cumin seeds","1/2 cup chopped onion","1/2 cup diced carrot","1/2 cup green peas","1/2 cup chopped tomato","1/2 tsp turmeric","3/4 tsp salt, or to taste","3 cups (750 ml) water","2 tbsp chopped coriander"],method:["Dry-roast the dalia in a wide pan over medium heat for 4–5 minutes until lightly toasted. Set aside.","Heat the oil, add cumin and let it sizzle. Cook the onion for 3–4 minutes until soft.","Add carrot and peas and cook for 3 minutes. Add tomato, turmeric and salt; cook 2 minutes.","Return the dalia, add the water, bring to a boil, then cover and simmer 18–20 minutes until tender.","Rest covered for 5 minutes, fluff gently and fold in the coriander."],notes:["If the pack says the dalia is pre-roasted, shorten or skip the dry-roast.","Use less water for separate grains, more for a softer bowl."]},{slug:"besan-chilla",title:"Besan Chilla",product:"besan",image:"/img/besan-chilla.webp",alt:"Two golden besan chillas with green chutney",intro:"A savoury gram-flour batter with onion, coriander and ajwain, cooked on a tawa.",prep:"15 min",cook:"20 min",serves:"3",ingredients:["1 1/2 cups (180 g) Samriddhi Bhog Besan","1 cup (250 ml) water, plus more if needed","1/2 cup finely chopped onion","2 tbsp chopped coriander","1 small green chilli (optional)","1/2 tsp ajwain, lightly crushed","1/4 tsp turmeric","3/4 tsp salt","2–3 tsp oil for cooking"],method:["Whisk the besan, ajwain, turmeric and salt to break up any lumps.","Whisk in half the water to a thick batter, then the rest until it pours but still coats a spoon.","Fold in onion, coriander and chilli. Rest 10 minutes.","Heat a lightly oiled tawa over medium heat. Spread 1/3 cup batter into a thin round.","Drizzle oil around the edge and cook 2–3 minutes until set; turn and cook 1–2 minutes more."],notes:["Add extra water a tablespoon at a time — a very thin batter is hard to turn.","Stir the batter between chillas; the vegetables settle."]}],h=e=>null==e?"Price on confirmation":`₹${e.toLocaleString("en-IN")}`,c={left:"20+ Years of Purity \xb7 ISO Registered \xb7 Zero Adulteration",right:"Landline 033-2659 6736"},u=[{label:"Home",href:"/"},{label:"Products",href:"/products"},{label:"Infrastructure",href:"/infrastructure"},{label:"B2B",href:"/b2b"},{label:"About",href:"/about"},{label:"Contact",href:"/contact"}],m={atta:"Our flagship product. Zero blending, zero chemicals. The roti that brings families back to the table. Chakki ground from carefully sourced wheat, washed and cleaned before milling.",besan:"Finely ground chana dal. Rich aroma, no blending. Perfect for chilla, kadhi, ladoo, pakoras, and every recipe that deserves genuine besan flavour.",dalia:"Coarsely cracked whole wheat. High-fibre, clean, nutty taste. Perfect for porridge, khichdi, upma, and wholesome morning meals.",sattu:"Slow-roasted, coarsely ground. Traditional power food — protein-rich and deeply nourishing. Perfect for drinks, litti, paratha filling."},g={eyebrow:"B2B supply",title:"Supplying to 10000+ Businesses",serve:["Kirana Stores","Dhabas & Restaurants","Caterers","Sweet Shops","Cloud Kitchens","Retail Chains"],offer:["50 kg Bags","Custom Labelling","GST Invoice","Credit Terms","Dedicated Account Manager","Regular Supply Schedule"],pageTitle:"Grow with Us",pageIntro:"Join us today and boost your profit margins.",advantages:[{k:"100 MT/Day Production",d:"Large-scale production ensures we never miss a delivery. Consistent supply, always on time."},{k:"FSSAI Licensed",d:"Full compliance with food safety standards. Your business stays protected with our FSSAI licence."},{k:"Competitive Margins",d:"Direct from mill pricing. No middlemen, no unnecessary costs. Better margins for your business."}]}}}]);